/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void rsr_state_stop(void)
{
  rsr_set_state   (RSR_STATE_DISARM) ;

  #if RSR_DISARM_ENA == 1
  if(prog_retrieve_option (FEAT_SECURE_LOCK) == SECURE_LOCK_DISABLE) // only use standard disarm if Smart oem alarm control is disabled
    rsr_disarm (0) ; 
  #endif

  rsr_parking_pattern (RSR_PRK_CONSTANT) ;
}


